console.log("loaded blocker.js");

(function () {
  console.log("inited blocker.js");
  "use strict";
  if (window.__blocker) return;

  var CONFIG = {
    hosts: ["eporner.com"],
    log: { level: "debug", trace: true, mute: [] },
    tabunder: {
      enabled: true,
      blockAllOpens: true,
      sameUrlOnly: true,
      armedWindow: 700,
      guardNavigation: true
    },
    video: {
      enabled: true,
      allow: [],
      pretendFinished: true,
      killFrames: true,
      mediaExt: /\.(m3u8|mpd|ts|m4s|mp4|webm|mov|aac|m4a)(\?|$)/i
    }
  };

  var LEVELS = { silent: 0, error: 1, warn: 2, info: 3, debug: 4 };
  var S = {
    tag: "color:#fff;background:#7c3aed;padding:1px 6px;border-radius:3px;font-weight:600",
    mod: "color:#a78bfa;font-weight:600",
    block: "color:#fff;background:#dc2626;padding:1px 6px;border-radius:3px;font-weight:600",
    ok: "color:#16a34a;font-weight:600",
    dim: "color:#9ca3af",
    plain: "color:inherit;background:none;font-weight:normal"
  };

  var counters = Object.create(null);
  var t0 = performance.now();

  function ms() {
    return (performance.now() - t0).toFixed(1) + "ms";
  }

  function enabled(level, mod) {
    if (LEVELS[CONFIG.log.level] < LEVELS[level]) return false;
    if (mod && CONFIG.log.mute.indexOf(mod) !== -1) return false;
    return true;
  }

  function emit(method, level, mod, style, label, args) {
    if (!enabled(level, mod)) return;
    var head = ["%c" + label + "%c %c" + mod + "%c " + ms(), style, S.plain, S.mod, S.dim];
    console[method].apply(console, head.concat(args));
  }

  var log = {
    debug: function () {
      emit("log", "debug", arguments[0], S.tag, "blocker", [].slice.call(arguments, 1));
    },
    info: function () {
      emit("info", "info", arguments[0], S.tag, "blocker", [].slice.call(arguments, 1));
    },
    warn: function () {
      emit("warn", "warn", arguments[0], S.tag, "blocker", [].slice.call(arguments, 1));
    },
    error: function () {
      emit("error", "error", arguments[0], S.tag, "blocker", [].slice.call(arguments, 1));
    },
    block: function (mod, key) {
      var rest = [].slice.call(arguments, 2);
      var id = mod + "." + key;
      counters[id] = (counters[id] || 0) + 1;
      if (!enabled("warn", mod)) return;
      emit("warn", "warn", mod, S.block, "BLOCK", [key].concat(rest));
      if (CONFIG.log.trace && enabled("debug", mod)) {
        console.groupCollapsed("%ccall stack%c", S.dim, S.plain);
        console.trace();
        console.groupEnd();
      }
    },
    patch: function (name) {
      counters["patch." + name] = 1;
      emit("log", "debug", "init", S.tag, "blocker", ["%cpatch%c " + name, S.ok, S.plain]);
    }
  };

  function install(name, fn) {
    try {
      fn();
      log.patch(name);
    } catch (e) {
      log.error("init", "patch failed: " + name, e);
    }
  }

  function onHost(p) {
    return location.hostname === p || location.hostname.slice(-(p.length + 1)) === "." + p;
  }

  var MULTI = [
    "co.uk", "org.uk", "ac.uk", "gov.uk", "co.jp", "or.jp", "ne.jp",
    "com.au", "net.au", "org.au", "com.br", "com.cn", "com.tr",
    "co.kr", "co.nz", "co.za", "com.mx", "com.ar", "com.pl"
  ];

  function registrable(hostname) {
    var parts = String(hostname).toLowerCase().split(".").filter(Boolean);
    if (parts.length <= 2) return parts.join(".");
    var lastTwo = parts.slice(-2).join(".");
    return MULTI.indexOf(lastTwo) !== -1 ? parts.slice(-3).join(".") : lastTwo;
  }

  var SELF = registrable(location.hostname);
  var ALLOW = CONFIG.video.allow.map(registrable);

  function isForeign(url) {
    if (!url) return false;
    var s = String(url);
    if (/^(blob|data|mediasource|about):/i.test(s)) return false;
    var parsed;
    try {
      parsed = new URL(s, location.href);
    } catch (e) {
      return false;
    }
    if (!/^https?:$/.test(parsed.protocol)) return false;
    var domain = registrable(parsed.hostname);
    return domain !== SELF && ALLOW.indexOf(domain) === -1;
  }

  var nativeAdd = EventTarget.prototype.addEventListener;

  function listen(target, type, fn, opts) {
    return nativeAdd.call(target, type, fn, opts);
  }

  var matched = false;
  for (var i = 0; i < CONFIG.hosts.length; i++) {
    if (onHost(CONFIG.hosts[i])) matched = true;
  }
  if (!matched) {
    log.debug("init", "host not listed: " + location.hostname);
    return;
  }

  console.log("%cblocker%c start on " + location.hostname, S.tag, S.plain);
  log.info("init", "self domain (eTLD+1):", SELF);
  log.info("init", "readyState:", document.readyState);
  log.info("init", "scripts already in DOM:", document.scripts.length);
  if (document.readyState !== "loading" || document.scripts.length > 1) {
    log.warn("init", "started late: page scripts may already hold native refs. Check run_at=document_start and world=MAIN");
  }

  var armedUntil = 0;
  var caughtThisGesture = false;

  function isArmed() {
    return Date.now() < armedUntil;
  }

  if (CONFIG.tabunder.enabled) {
    var T = CONFIG.tabunder;

    install("gesture-arm", function () {
      var types = ["pointerdown", "mousedown", "touchstart", "click"];
      types.forEach(function (type) {
        listen(window, type, function (e) {
          armedUntil = Date.now() + T.armedWindow;
          caughtThisGesture = false;
          log.debug("tabunder", "gesture " + type + " on", e.target && e.target.tagName, "armed for " + T.armedWindow + "ms");
        }, true);
      });
    });

    install("window.open", function () {
      var nativeOpen = window.open;

      function ghost() {
        return new Proxy(function () {}, {
          get: function (t, prop) {
            if (prop === "closed") return false;
            if (prop === "then") return undefined;
            if (prop === "toString" || prop === "valueOf" || prop === Symbol.toPrimitive) {
              return function () { return ""; };
            }
            log.debug("tabunder", "ghost window read:", String(prop));
            return ghost();
          },
          set: function (t, prop) {
            log.debug("tabunder", "ghost window write:", String(prop));
            return true;
          },
          apply: function () { return ghost(); },
          construct: function () { return ghost(); }
        });
      }

      window.open = function (url, target, features) {
        var resolved = String(url || "");
        var sameUrl = resolved === "" || resolved === location.href || resolved === location.href.split("#")[0];
        var reasons = [];
        if (T.blockAllOpens) reasons.push("blockAllOpens");
        if (T.sameUrlOnly && sameUrl) reasons.push("clone of current url");
        if (isArmed()) reasons.push("inside click window");

        if (reasons.length) {
          caughtThisGesture = true;
          log.block("tabunder", "window.open", {
            url: resolved || "(empty)",
            target: target,
            features: features,
            reason: reasons.join(", ")
          });
          return ghost();
        }
        log.info("tabunder", "window.open allowed:", resolved);
        return nativeOpen.apply(window, arguments);
      };
      window.open.toString = nativeOpen.toString.bind(nativeOpen);
    });

    install("HTMLElement.click", function () {
      var nativeClick = HTMLElement.prototype.click;
      HTMLElement.prototype.click = function () {
        if (this instanceof HTMLAnchorElement && /^_blank$/i.test(this.target || "") && !this.isConnected) {
          caughtThisGesture = true;
          log.block("tabunder", "synthetic click", { href: this.href });
          return;
        }
        return nativeClick.apply(this, arguments);
      };
      HTMLElement.prototype.click.toString = nativeClick.toString.bind(nativeClick);
    });

    install("dispatchEvent", function () {
      var nativeDispatch = EventTarget.prototype.dispatchEvent;
      EventTarget.prototype.dispatchEvent = function (event) {
        if (event && event.type === "click" && this instanceof HTMLAnchorElement && /^_blank$/i.test(this.target || "") && !this.isConnected) {
          caughtThisGesture = true;
          log.block("tabunder", "dispatchEvent click", { href: this.href });
          return true;
        }
        return nativeDispatch.apply(this, arguments);
      };
    });

    install("addEventListener-filter", function () {
      var SUSPECT = [
        /\bwindow\s*\.\s*open\s*\(/,
        /\bopen\s*\(\s*(location|window\.location|document\.URL)/,
        /location\s*(\.\s*href)?\s*=\s*["']https?:/,
        /\.\s*assign\s*\(\s*["']https?:/
      ];
      var CLICKY = /^(click|mousedown|mouseup|pointerdown|pointerup|touchstart|touchend)$/i;

      EventTarget.prototype.addEventListener = function (type, listener) {
        if (typeof listener === "function" && CLICKY.test(String(type))) {
          var src = "";
          try {
            src = Function.prototype.toString.call(listener);
          } catch (e) {}
          for (var j = 0; j < SUSPECT.length; j++) {
            if (SUSPECT[j].test(src)) {
              log.block("tabunder", "listener rejected", {
                event: type,
                pattern: String(SUSPECT[j]),
                code: src.slice(0, 200)
              });
              return;
            }
          }
        }
        return nativeAdd.apply(this, arguments);
      };
      EventTarget.prototype.addEventListener.toString = nativeAdd.toString.bind(nativeAdd);
    });

    if (T.guardNavigation) {
      install("beforeunload-guard", function () {
        listen(window, "beforeunload", function (e) {
          if (!caughtThisGesture || !isArmed()) return;
          log.block("tabunder", "navigation away", "confirm requested");
          e.preventDefault();
          e.returnValue = "";
          return "";
        });
      });
    }
  }

  if (CONFIG.video.enabled) {
    var V = CONFIG.video;
    var handled = new WeakSet();

    function describe(el) {
      return {
        tag: el.tagName,
        id: el.id || undefined,
        cls: el.className || undefined,
        src: el.currentSrc || el.getAttribute("src") || undefined
      };
    }

    function neutralize(el, reason, detail) {
      if (handled.has(el)) {
        log.debug("video", "already handled, skip:", reason);
        return;
      }
      handled.add(el);
      var info = describe(el);
      if (detail) {
        for (var k in detail) info[k] = detail[k];
      }
      log.block("video", reason, info);

      try { el.pause(); } catch (e) {}

      if (V.pretendFinished) {
        var events = ["loadedmetadata", "canplay", "playing", "timeupdate", "ended"];
        setTimeout(function () {
          events.forEach(function (type) {
            try {
              el.dispatchEvent(new Event(type));
            } catch (e) {
              log.error("video", "cannot fire " + type, e);
            }
          });
          log.debug("video", "fed player:", events.join(" > "));
        }, 0);
      } else {
        el.removeAttribute("src");
        try { el.load(); } catch (e) {}
      }
    }

    install("media.src", function () {
      var desc = Object.getOwnPropertyDescriptor(HTMLMediaElement.prototype, "src");
      if (!desc || !desc.set) throw new Error("no src descriptor");
      Object.defineProperty(HTMLMediaElement.prototype, "src", {
        configurable: true,
        enumerable: desc.enumerable,
        get: function () {
          return desc.get.call(this);
        },
        set: function (value) {
          if (isForeign(value)) {
            neutralize(this, "foreign src assigned", { value: String(value) });
            return;
          }
          log.debug("video", "own src allowed:", String(value).slice(0, 120));
          handled["delete"](this);
          return desc.set.call(this, value);
        }
      });
    });

    install("setAttribute", function () {
      var native = Element.prototype.setAttribute;
      Element.prototype.setAttribute = function (name, value) {
        if (/^src$/i.test(String(name)) && (this instanceof HTMLMediaElement || this instanceof HTMLSourceElement) && isForeign(value)) {
          var media = this instanceof HTMLSourceElement ? this.parentElement : this;
          if (media instanceof HTMLMediaElement) {
            neutralize(media, "setAttribute src", { value: String(value) });
            return;
          }
        }
        return native.apply(this, arguments);
      };
      Element.prototype.setAttribute.toString = native.toString.bind(native);
    });

    install("media.play", function () {
      var nativePlay = HTMLMediaElement.prototype.play;
      HTMLMediaElement.prototype.play = function () {
        var src = this.currentSrc || this.src;
        if (isForeign(src)) {
          neutralize(this, "play from foreign domain", { src: src });
          return Promise.resolve();
        }
        log.debug("video", "play allowed:", String(src).slice(0, 120));
        return nativePlay.apply(this, arguments);
      };
      HTMLMediaElement.prototype.play.toString = nativePlay.toString.bind(nativePlay);
    });

    var blockRequest = function (url) {
      return V.mediaExt.test(String(url)) && isForeign(url);
    };

    install("fetch", function () {
      var nativeFetch = window.fetch;
      if (!nativeFetch) throw new Error("no fetch");
      window.fetch = function (input) {
        var url = typeof input === "string" ? input : (input && input.url) || "";
        if (blockRequest(url)) {
          log.block("net", "fetch media", { url: url });
          return Promise.resolve(new Response(new ArrayBuffer(0), { status: 200, statusText: "OK" }));
        }
        if (V.mediaExt.test(url)) log.debug("net", "own media:", url.slice(0, 140));
        return nativeFetch.apply(this, arguments);
      };
      window.fetch.toString = nativeFetch.toString.bind(nativeFetch);
    });

    install("xhr", function () {
      var nativeOpen = XMLHttpRequest.prototype.open;
      var nativeSend = XMLHttpRequest.prototype.send;

      XMLHttpRequest.prototype.open = function (method, url) {
        this.__url = String(url);
        this.__blocked = blockRequest(url);
        return nativeOpen.apply(this, arguments);
      };

      XMLHttpRequest.prototype.send = function () {
        var xhr = this;
        if (!xhr.__blocked) return nativeSend.apply(xhr, arguments);
        log.block("net", "xhr media", { url: xhr.__url, type: xhr.responseType });

        function set(k, v) {
          Object.defineProperty(xhr, k, { value: v, configurable: true });
        }
        set("readyState", 4);
        set("status", 200);
        set("statusText", "OK");
        set("response", xhr.responseType === "arraybuffer" ? new ArrayBuffer(0) : "");
        set("responseText", "");

        setTimeout(function () {
          xhr.dispatchEvent(new Event("readystatechange"));
          xhr.dispatchEvent(new ProgressEvent("load"));
          xhr.dispatchEvent(new ProgressEvent("loadend"));
        }, 0);
      };
    });

    install("dom-scan", function () {
      function scan(root) {
        if (!root || root.nodeType !== 1) root = document;

        var media = root.querySelectorAll("video, audio");
        for (var m = 0; m < media.length; m++) {
          var el = media[m];
          var src = el.currentSrc || el.getAttribute("src") || "";
          if (isForeign(src)) {
            neutralize(el, "element with foreign src", { src: src });
            continue;
          }
          var sources = el.querySelectorAll("source[src]");
          for (var s = 0; s < sources.length; s++) {
            if (isForeign(sources[s].getAttribute("src"))) {
              log.debug("dom", "source removed:", sources[s].getAttribute("src"));
              sources[s].remove();
              neutralize(el, "foreign source element");
            }
          }
        }

        if (!V.killFrames) return;
        var frames = root.querySelectorAll("iframe[src]");
        for (var f = 0; f < frames.length; f++) {
          var fsrc = frames[f].getAttribute("src");
          if (isForeign(fsrc) && /player|embed|video|vast|vpaid/i.test(fsrc)) {
            log.block("dom", "player iframe", { src: fsrc });
            frames[f].remove();
          }
        }
      }

      function start() {
        scan(document);
        new MutationObserver(function (records) {
          records.forEach(function (r) {
            for (var n = 0; n < r.addedNodes.length; n++) {
              if (r.addedNodes[n].nodeType === 1) scan(r.addedNodes[n]);
            }
            if (r.type === "attributes") scan(r.target.parentElement);
          });
        }).observe(document.documentElement, {
          childList: true,
          subtree: true,
          attributes: true,
          attributeFilter: ["src"]
        });
        log.debug("dom", "observer attached");
      }

      if (document.documentElement) start();
      else listen(document, "DOMContentLoaded", start, { once: true });
    });
  }

  function stats() {
    var rows = [];
    for (var key in counters) {
      if (key.indexOf("patch.") === 0) continue;
      rows.push({ key: key, hits: counters[key] });
    }
    if (!rows.length) {
      console.log("%cblocker%c nothing blocked yet", S.tag, S.plain);
      return;
    }
    console.table(rows);
  }

  listen(window, "pagehide", function () {
    log.info("init", "page unloading, summary:");
    stats();
  });

  Object.defineProperty(window, "__blocker", {
    value: {
      config: CONFIG,
      counters: counters,
      stats: stats,
      level: function (v) {
        if (!(v in LEVELS)) {
          console.warn("levels:", Object.keys(LEVELS).join(", "));
          return;
        }
        CONFIG.log.level = v;
        console.log("%cblocker%c log level:", S.tag, S.plain, v);
      },
      trace: function (on) {
        CONFIG.log.trace = !!on;
        console.log("%cblocker%c stacks:", S.tag, S.plain, CONFIG.log.trace);
      },
      isForeign: isForeign,
      registrable: registrable
    },
    enumerable: false
  });

  log.info("init", "ready - call __blocker.stats() for summary");
})();
